// nextgit — parity dashboard renderer (platform/ui/parity.html).
//
// Renders the PARITY_TABLE contract (from ./parity-data.js, generated by
// porting/parity/compare.mjs) into the document. Pure DOM construction:
// every string from the data module is inserted via textContent — the
// XSS control (injected markup in the data renders as text, never as
// live attributes/elements). No fetch, no worker dependency, no timers
// (the ?probe=1 live-render seam needs nothing to settle: the page is
// synchronous once the module loads).

import { PARITY_TABLE } from "./parity-data.js";

// textContent is the ONLY string sink into the DOM. Every value from
// the data module — dimension names, evidence, sources, verdicts —
// is inserted through it, so hostile content in the data renders as
// text, never as live attributes/elements (pinned by the
// capability-parity suite's XSS probe leg).

const VERDICT_CLASS = { exceeds: "verdict-exceeds", parity: "verdict-parity", below: "verdict-below" };
const STATUS_CLASS = { shipped: "status-shipped", partial: "status-partial", none: "status-none" };

const el = (tag, className, text) => {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text; // textContent is escape-safe by construction
  return node;
};

const statusLabel = (s) => (s === "none" ? "—" : s);

const renderRow = (d) => {
  const tr = document.createElement("tr");
  // Below rows carry the verdict class on the row (the parity suite
  // counts .verdict-below rows) AND on the verdict cell.
  if (d.verdict === "below") tr.className = "verdict-below";

  const verdictCell = el("td", `verdict-cell ${VERDICT_CLASS[d.verdict] ?? ""}`, d.verdict);
  const dimCell = el("td", "dim");
  dimCell.textContent = d.dimension;

  const ghCell = el("td", `status ${STATUS_CLASS[d.github.status] ?? ""}`, statusLabel(d.github.status));
  const ngCell = el("td", `status ${STATUS_CLASS[d.nextgit.status] ?? ""}`, statusLabel(d.nextgit.status));

  const ghEvidence = el("td", "evidence");
  ghEvidence.textContent = d.github.evidence;
  const ngEvidence = el("td", "evidence");
  ngEvidence.textContent = d.nextgit.evidence;

  tr.append(verdictCell, dimCell, ghCell, ngCell, ghEvidence, ngEvidence);
  return tr;
};

const render = () => {
  const { generated, dimensions } = PARITY_TABLE;

  const gen = document.getElementById("parity-generated");
  if (gen) gen.textContent = `generated ${generated}`;

  const counts = { exceeds: 0, parity: 0, below: 0 };
  for (const d of dimensions) counts[d.verdict] = (counts[d.verdict] ?? 0) + 1;
  for (const v of ["exceeds", "parity", "below"]) {
    const chip = document.getElementById(`chip-${v}`);
    if (chip) chip.textContent = String(counts[v] ?? 0);
  }

  const tbody = document.getElementById("parity-tbody");
  if (tbody) {
    tbody.textContent = "";
    for (const d of dimensions) tbody.appendChild(renderRow(d));
  }
};

render();
